#pragma once
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <deque>
#include <mutex>
#include <optional>

namespace ws {

class BlockDeque {
public:
    using Clock = std::chrono::steady_clock;

    explicit BlockDeque(std::size_t capacity = 1000) noexcept : closed_(false), capacity_(capacity) {}
    ~BlockDeque() noexcept { Close(); }

    // Copy and move operations are deleted
    BlockDeque(const BlockDeque&) = delete;
    BlockDeque& operator=(const BlockDeque&) = delete;
    BlockDeque(BlockDeque&&) = delete;
    BlockDeque& operator=(BlockDeque&&) = delete;

    void Clear() noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        ClearNoLock();
    }

    bool Empty() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.empty();
    }

    bool Full() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        return Size() >= capacity_;
    }

    std::size_t Size() const noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.size();
    }

    std::size_t Capacity() const noexcept { return capacity_; }

    const T& Front() const noexcept {
        assert(!Empty());
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.front();
    }

    const T& Back() const noexcept {
        assert(!Empty());
        std::lock_guard<std::mutex> locker(mtx_);
        return deq_.back();
    }

    T& Front() noexcept { return const_cast<T&>(static_cast<const BlockDeque*>(this)->Front()); }
    T& Back() noexcept { return const_cast<T&>(static_cast<const BlockDeque*>(this)->Back()); }

    void PushBack(T item) noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        WaitForSpace(locker);
        deq_.push_back(std::move(item));
        consumer_cond_.notify_one();
    }

    void PushFront(T item) noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        WaitForSpace(locker);
        deq_.push_front(std::move(item));
        consumer_cond_.notify_one();
    }

    std::optional<T> Pop(std::optional<Clock::duration> time_out = std::nullopt) noexcept {
        std::unique_lock<std::mutex> locker(mtx_);
        if (closed_) return std::nullopt;
        if (deq_.empty()) {
            if (!time_out.has_value()) {
                consumer_cond_.wait(locker, [this] { return !deq_.empty() || closed_; });
            } else {
                if (consumer_cond_.wait_for(locker, time_out.value(), [this] { return !deq_.empty() || closed_; }) == std::cv_status::timeout) {
                    return std::nullopt;
                }
            }
        }
        if (closed_) return std::nullopt;
        T item = std::move(deq_.front());
        deq_.pop_front();
        producer_cond_.notify_one();
        return item;
    }

    void Flush() noexcept {
        consumer_cond_.notify_one();
    }

    void Close() noexcept {
        std::lock_guard<std::mutex> locker(mtx_);
        ClearNoLock();
        closed_ = true;
        producer_cond_.notify_all();
        consumer_cond_.notify_all();
    }

private:
    void WaitForSpace(std::unique_lock<std::mutex>& locker) noexcept {
        while (Full() && !closed_) {
            producer_cond_.wait(locker);
        }
        if (closed_) return;
    }

    void ClearNoLock() noexcept { deq_.clear(); }

    mutable std::mutex mtx_;
    std::atomic_bool closed_;
    const std::size_t capacity_;
    std::deque<T> deq_;
    std::condition_variable consumer_cond_;
    std::condition_variable producer_cond_;
};

} // namespace ws
